export function aiWagesSvg(lang, kind, mobile = false) {
  if (!['fr', 'en'].includes(lang) || !AI_WAGES_KINDS.includes(kind) || typeof mobile !== 'boolean') {
    throw new TypeError('Invalid AI wages figure variant');
  }
  return variants[`${kind}-${lang}-${mobile ? 'mobile' : 'desktop'}`];
}
